#!/usr/bin/env bash
#
# One-time release bootstrap: publish the current workspace versions with your
# own npm login, then register the Release workflow as a trusted publisher so
# CI publishes via OIDC from then on. Re-runnable; already-done steps are skipped.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
REPO_SLUG="dereknex/fast-jev-compaction"
WORKFLOW_FILE="release.yml"

# version_ge A B: true when version A is >= version B (numeric x.y.z).
version_ge() {
  local IFS=. a b i
  read -ra a <<< "$1"
  read -ra b <<< "$2"
  for i in 0 1 2; do
    (( ${a[i]:-0} > ${b[i]:-0} )) && return 0
    (( ${a[i]:-0} < ${b[i]:-0} )) && return 1
  done
  return 0
}

# publishable_packages prints name@version for workspaces with a publishConfig
# (that is what changesets publishes; claude-code is private to this repo).
publishable_packages() {
  node -e '
    const fs = require("fs"), path = require("path");
    for (const dir of fs.readdirSync("packages").sort()) {
      const file = path.join("packages", dir, "package.json");
      if (!fs.existsSync(file)) continue;
      const pkg = JSON.parse(fs.readFileSync(file, "utf8"));
      if (pkg.name && pkg.version && pkg.publishConfig) console.log(`${pkg.name}@${pkg.version}`);
    }'
}

is_published() {
  npm view "$1" version >/dev/null 2>&1
}

# trust_state PKG: prints "publish|<id>", "stage|<id>" or "none|" for this repo +
# release workflow. Configs created after 2026-09-03 default to stage publish only,
# which makes CI's `npm publish` fail with E403 "OIDC permission denied for this action".
trust_state() {
  local out id
  out=$(npm trust list "$1" --json 2>/dev/null) || { printf 'none|'; return; }
  if ! printf '%s' "$out" | grep -Eq "\"repository\": *\"$REPO_SLUG\"" ||
     ! printf '%s' "$out" | grep -Eq "\"file\": *\"$WORKFLOW_FILE\""; then
    printf 'none|'
    return
  fi
  id=$(printf '%s' "$out" | grep -o '"id": *"[^"]*"' | head -1 | sed 's/.*"\([^"]*\)"/\1/')
  if printf '%s' "$out" | grep -q '"createPackage"'; then printf 'publish|%s' "$id"; else printf 'stage|%s' "$id"; fi
}

banner "fast-jev-compaction: first publish → trusted publisher"

stage "Preflight"
say "Checking the local toolchain the bootstrap needs."
for tool in node npm git; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not on PATH"; exit 1; }
done
[[ -f package.json && -d packages ]] || { warn "run this from the repository root"; exit 1; }
[[ -f ".github/workflows/$WORKFLOW_FILE" ]] || { warn ".github/workflows/$WORKFLOW_FILE is missing"; exit 1; }

NODE_VERSION=$(node -p 'process.versions.node')
version_ge "$NODE_VERSION" 22.14.0 || { warn "Node $NODE_VERSION is too old; trusted publishing needs >= 22.14.0"; exit 1; }
say "node $NODE_VERSION ✓"

NPM_VERSION=$(npm -v)
if ! version_ge "$NPM_VERSION" 11.15.0; then
  warn "npm $NPM_VERSION is too old; 'npm trust' needs >= 11.15.0"
  step "Run: npm install -g npm@^11.15.0"
  step "Then re-run: bash scripts/setup-release.sh"
  exit 1
fi
say "npm $NPM_VERSION ✓ (needs >= 11.15.0 for 'npm trust')"

if [[ -n "$(git status --porcelain)" ]]; then
  warn "working tree is dirty; the published tarballs are built from these files"
  git status --short | sed 's/^/    /'
  confirm "Publish from this working tree anyway?" || exit 1
else
  say "working tree clean ✓"
fi
[[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || warn "not on main; the workflow fix must reach main before CI can release"

PUBLISHABLE=()
while IFS= read -r spec; do PUBLISHABLE+=("$spec"); done < <(publishable_packages)
(( ${#PUBLISHABLE[@]} )) || { warn "no publishable workspace packages found"; exit 1; }
say "publishable packages: ${PUBLISHABLE[*]}"

confirm "Install, build, and test before publishing?" || exit 1
npm ci
npm run build
npm test

stage "npm login + package ownership"
say "Both steps below need an npm account with write access to the packages,"
say "and 2FA enabled on that account (npm requires it for 'npm trust')."
if npm whoami >/dev/null 2>&1; then
  NPM_USER=$(npm whoami)
  say "Already logged in as $NPM_USER."
else
  step "A browser opens; sign in to npm."
  npm login
  NPM_USER=$(npm whoami) || { warn "npm login did not complete"; exit 1; }
fi
note "scopes in this repo: $(printf '%s\n' "${PUBLISHABLE[@]}" | sed 's|/.*||' | sort -u | tr '\n' ' ') — you can publish only to @<your npm username> or an org you belong to."

MISSING_OWNER=()
for spec in "${PUBLISHABLE[@]}"; do
  name="${spec%@*}"
  if ! owner_list=$(npm owner ls "$name" 2>/dev/null); then
    warn "$name: no owner list from the registry — publishing it will create the package"
    continue
  fi
  if printf '%s\n' "$owner_list" | awk '{print $1}' | grep -qx "$NPM_USER"; then
    say "$name: $NPM_USER is an owner ✓"
  else
    MISSING_OWNER+=("$name (owners: $(printf '%s\n' "$owner_list" | awk '{print $1}' | tr '\n' ' '))")
  fi
done
if (( ${#MISSING_OWNER[@]} )); then
  warn "You ($NPM_USER) do not have write access to:"
  for entry in "${MISSING_OWNER[@]}"; do note "  - $entry"; done
  step "Publishing and trusted-publisher setup both need write access."
  step "Ask an existing owner to grant access (or transfer the package), then re-run."
  exit 1
fi

stage "First publish (bootstrap, from your machine)"
say "CI cannot publish until a trusted publisher exists, and a trusted publisher"
say "can only be attached to a package that is already on npm."
say "So publish any missing workspace versions once, with your own login."
for spec in "${PUBLISHABLE[@]}"; do
  name="${spec%@*}"
  version="${spec##*@}"
  if is_published "$spec"; then
    say "$spec is already on npm — skipping."
    continue
  fi
  step "Previewing $spec"
  npm publish --workspace="$name" --access public --no-provenance --dry-run | tail -n 6
  note "--no-provenance: provenance needs CI OIDC; the bootstrap tarball has none."
  if confirm "Publish $name@$version to npm now?"; then
    # npm may prompt for a 2FA one-time password here.
    npm publish --workspace="$name" --access public --no-provenance
    is_published "$spec" || { warn "$spec is still not readable from the registry"; exit 1; }
    say "$spec published ✓"
  else
    SKIPPED+=("publish $name@$version")
  fi
done

stage "Trusted publisher (GitHub Actions)"
say "Registers this repo's release workflow so CI can publish via OIDC, with no"
say "NPM_TOKEN: $REPO_SLUG → .github/workflows/$WORKFLOW_FILE"
for spec in "${PUBLISHABLE[@]}"; do
  name="${spec%@*}"
  IFS='|' read -r state trust_id <<< "$(trust_state "$name")"
  if [[ "$state" == "publish" ]]; then
    say "$name trusts $REPO_SLUG/$WORKFLOW_FILE with npm publish — skipping."
    continue
  fi
  if [[ "$state" == "stage" ]]; then
    warn "$name only allows this workflow to stage-publish; CI runs 'npm publish' (E403)"
    if [[ -n "$trust_id" ]] && confirm "Replace the trusted publisher for $name (revoke + re-add with --allow-publish)?"; then
      if npm trust revoke "$name" --id="$trust_id" &&
         npm trust github "$name" --repo "$REPO_SLUG" --file "$WORKFLOW_FILE" --allow-publish -y; then
        IFS='|' read -r state trust_id <<< "$(trust_state "$name")"
      else
        warn "$name: revoke/re-add failed"
        state=failed
      fi
    else
      open_url "https://www.npmjs.com/package/$name/access"
      step "Remove the GitHub Actions entry, re-add it with 'npm publish' enabled."
      pause "Press Enter once $name allows npm publish"
      IFS='|' read -r state trust_id <<< "$(trust_state "$name")"
    fi
    if [[ "$state" == "publish" ]]; then
      say "$name trusted ✓ (publish allowed)"
    else
      SKIPPED+=("npm publish permission for $name")
    fi
    continue
  fi
  if confirm "Add trusted publisher for $name?"; then
    if npm trust github "$name" --repo "$REPO_SLUG" --file "$WORKFLOW_FILE" --allow-publish -y &&
       [[ "$(trust_state "$name")" == publish* ]]; then
      say "$name trusted ✓ (publish allowed)"
    else
      warn "$name: trusted publisher was not created (2FA enabled on the account?)"
      SKIPPED+=("trusted publisher for $name")
    fi
  else
    SKIPPED+=("trusted publisher for $name")
  fi
done

stage "Verify end state"
say "Repo-side requirements for OIDC publishing:"
if grep -q "id-token: write" ".github/workflows/$WORKFLOW_FILE" &&
   grep -q "npm install -g npm@\\^11.5.1" ".github/workflows/$WORKFLOW_FILE"; then
  say "  id-token: write + npm >= 11.5.1 in $WORKFLOW_FILE ✓"
else
  warn "$WORKFLOW_FILE is missing 'id-token: write' or the npm upgrade step"
  SKIPPED+=("commit the OIDC setup in .github/workflows/$WORKFLOW_FILE")
fi
if [[ -n "$(git status --porcelain -- ".github/workflows/$WORKFLOW_FILE")" ]]; then
  warn "$WORKFLOW_FILE has uncommitted changes — commit and push them before the next release"
  SKIPPED+=("commit + push .github/workflows/$WORKFLOW_FILE")
fi

say ""
say "From here on, releases are automatic:"
step "npm run changeset → commit the changeset file → merge to main"
step "merge the 'Version Packages' PR it opens; Release then publishes via OIDC"
step "watch it: gh run list --workflow=$WORKFLOW_FILE"
note "The next CI publish is the real end-to-end test of the trust setup."

finish
